package android.graphics;public class RectF{public float left,top,right,bottom;public RectF(float l,float t,float r,float b){left=l;top=t;right=r;bottom=b;}public RectF(Rect r){this(r.left,r.top,r.right,r.bottom);}public float width(){return right-left;}public float height(){return bottom-top;}public boolean intersect(RectF r){if(left<r.right && right>r.left && top<r.bottom && bottom>r.top){left=Math.max(left,r.left);top=Math.max(top,r.top);right=Math.min(right,r.right);bottom=Math.min(bottom,r.bottom);return true;}return false;}}